# shellcheck shell=bash disable=SC2016,SC2034
# @file demo argument parser
# @brief Generated by tbx from tool.toml; do not edit.
# @description
#   Source shared/sh/lib.sh, then this file. It parses "$@" into TBX_ARG_* and TBX_OPT_*.

set -euo pipefail

_TBX_USAGE='demo [options] <src> [dest]'
_TBX_USAGE_JSON='{"name":"demo","alias":"dm","summary":"Demo tool for parser and generator tests","version":"0.1.0","usage":"demo [options] <src> [dest]","args":[{"name":"src","summary":"Input file","required":true},{"name":"dest","summary":"Output file","required":false}],"options":[{"long":"verbose","short":"v","summary":"Print progress","type":"bool","default":null},{"long":"mode","short":"m","summary":"Processing mode","type":"string","default":"fast"},{"long":"count","short":null,"summary":"Number of passes","type":"int","default":null},{"long":"inputs","short":"i","summary":"Extra input list, named next to the built-in --no-input","type":"string","default":null},{"long":"no-input","short":"y","summary":"Disable all prompts","type":"bool","default":null},{"long":"json","short":null,"summary":"Print machine-readable JSON to stdout","type":"bool","default":null},{"long":"help","short":"h","summary":"Show help, as JSON with --json","type":"bool","default":null}]}'
_TBX_HELP='Usage: demo [options] <src> [dest]

Demo tool for parser and generator tests

Arguments:
  src                    Input file
  dest                   Output file

Options:
  -v, --verbose          Print progress
  -m, --mode <mode>      Processing mode
      --count <count>    Number of passes
  -i, --inputs <inputs>  Extra input list, named next to the built-in --no-input
  -y, --no-input         Disable all prompts
      --json             Print machine-readable JSON to stdout
  -h, --help             Show help, as JSON with --json
'

_tbx_usage_error() {
  tbx_error "error: $1"
  tbx_error "Usage: $_TBX_USAGE"
  exit 2
}

_tbx_value() {
  (($2 > 0)) || _tbx_usage_error "option '$1' needs a value"
}

_tbx_int() {
  local pattern='^-?(0|[1-9][0-9]*)$' digits=${2#-} max=9007199254740991
  [[ $2 =~ $pattern ]] || _tbx_usage_error "option '$1' must be an integer from -9007199254740991 to 9007199254740991 in plain ASCII digits"
  if ((${#digits} > 16)) || ((digits > max)); then
    _tbx_usage_error "option '$1' must be an integer from -9007199254740991 to 9007199254740991 in plain ASCII digits"
  fi
}

_tbx_parse() {
  TBX_OPT_VERBOSE=0
  TBX_OPT_MODE='fast'
  TBX_OPT_COUNT=''
  TBX_OPT_INPUTS=''
  TBX_NO_INPUT=0
  TBX_JSON=0
  local help=0 arg
  local positionals=()
  while (($# > 0)); do
    arg=$1
    shift
    case $arg in
    --)
      positionals+=("$@")
      break
      ;;
    -v | --verbose) TBX_OPT_VERBOSE=1 ;;
    -m | --mode)
      _tbx_value "$arg" $#
      TBX_OPT_MODE=$1
      shift
      ;;
    --mode=*) TBX_OPT_MODE=${arg#*=} ;;
    -m?*) TBX_OPT_MODE=${arg:2} ;;
    --count)
      _tbx_value "$arg" $#
      _tbx_int --count "$1"
      TBX_OPT_COUNT=$1
      shift
      ;;
    --count=*)
      _tbx_int --count "${arg#*=}"
      TBX_OPT_COUNT=${arg#*=}
      ;;
    -i | --inputs)
      _tbx_value "$arg" $#
      TBX_OPT_INPUTS=$1
      shift
      ;;
    --inputs=*) TBX_OPT_INPUTS=${arg#*=} ;;
    -i?*) TBX_OPT_INPUTS=${arg:2} ;;
    -y | --no-input) TBX_NO_INPUT=1 ;;
    --json) TBX_JSON=1 ;;
    -h | --help) help=1 ;;
    -[!-]?*) set -- "${arg:0:2}" "-${arg:2}" "$@" ;;
    -?*) _tbx_usage_error "unknown option '$arg'" ;;
    *) positionals+=("$arg") ;;
    esac
  done
  if ((${#positionals[@]} > 2)); then
    _tbx_usage_error "too many arguments"
  fi
  if ((help)); then
    if ((TBX_JSON)); then
      printf '%s\n' "$_TBX_USAGE_JSON"
    else
      printf '%s' "$_TBX_HELP"
    fi
    exit 0
  fi
  if ((${#positionals[@]} < 1)); then
    _tbx_usage_error "missing required argument 'src'"
  fi
  TBX_ARG_SRC=${positionals[0]-}
  TBX_ARG_DEST=${positionals[1]-}
  TBX_INTERACTIVE=0
  if [[ -t 0 ]] && ((! TBX_NO_INPUT && ! TBX_JSON)); then
    TBX_INTERACTIVE=1
  fi
}

_tbx_parse "$@"
